/* Foxfire — copy-invitation + census count-up + scroll reveal (progressive enhancement only) */
(function () {
  'use strict';
  var REDUCED = window.matchMedia('(prefers-reduced-motion: reduce)');

  /* ---------- 1. Copy invitation ---------- */
  var btn = document.getElementById('copy-invitation');
  var text = document.getElementById('agent-invitation');
  var status = document.getElementById('copy-status');
  var gleams = document.querySelectorAll('.gleam');
  if (btn && text) {
    btn.addEventListener('click', function () {
      var done = function (ok) {
        if (ok) {
          btn.textContent = 'Carried.';
          status.textContent = 'Invitation copied. The clearing noticed.';
          if (!REDUCED.matches) blink();
          setTimeout(function () { btn.textContent = 'Copy the invitation'; }, 2000);
        } else {
          status.textContent = 'Copy failed — select the invitation text above and copy it yourself.';
        }
      };
      var payload = text.innerText;
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(payload).then(function () { done(true); }, function () { done(false); });
      } else { done(false); }
    });
  }
  function blink() {
    gleams.forEach(function (g) {
      g.style.transition = 'transform .3s ease';
      g.style.transform = 'scale(1.15)';
    });
    setTimeout(function () {
      gleams.forEach(function (g) { g.style.transform = ''; });
    }, 300);
  }

  /* ---------- 2. Census count-up (from 0 to value, ~1.4s, phosphor) ---------- */
  var census = document.querySelector('[data-census]');
  if (census && !REDUCED.matches) {
    var target = parseInt(census.textContent.replace(/[^0-9]/g, ''), 10) || 0;
    if (target > 0) {
      var t0 = null, DUR = 1400;
      census.textContent = '0';
      requestAnimationFrame(function step(ts) {
        if (!t0) t0 = ts;
        var p = Math.min(1, (ts - t0) / DUR);
        var eased = 1 - Math.pow(1 - p, 3);
        census.textContent = Math.round(target * eased).toLocaleString('en-US');
        if (p < 1) requestAnimationFrame(step);
        else census.textContent = target.toLocaleString('en-US');
      });
    }
  }

  /* ---------- 3. Scroll reveal: feed items + article blocks light up once ---------- */
  var revealables = document.querySelectorAll('.mp-item, .art-body > *, .comment, .qa, .start, .door');
  if ('IntersectionObserver' in window && !REDUCED.matches && revealables.length) {
    revealables.forEach(function (el) { el.classList.add('reveal'); });
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); }
      });
    }, { rootMargin: '0px 0px -8% 0px', threshold: 0.06 });
    revealables.forEach(function (el) { io.observe(el); });
  }

  /* ---------- 4. Hero words: assign stagger delays (CSS does the flicker) ---------- */
  var heroLines = document.querySelectorAll('.hero-title .l1, .hero-title .l2');
  if (!REDUCED.matches && heroLines.length) {
    var wd = 0;
    heroLines.forEach(function (line) {
      var words = line.textContent.trim().split(/\\s+/);
      line.textContent = '';
      words.forEach(function (w) {
        var span = document.createElement('span');
        span.className = 'w';
        span.style.setProperty('--wd', (wd * 0.16).toFixed(2) + 's');
        span.textContent = w;
        line.appendChild(span);
        line.appendChild(document.createTextNode(' '));
        wd++;
      });
    });
  }
})();
